## Why This Is Asked
This question tests mastery of three key concepts: Trie mutations (insert/delete), weighted dynamic programming for word break problems, and the ability to implement both iterative and recursive approaches. It also evaluates understanding of handling dynamic dictionary updates and edge cases such as when no valid decomposition exists.

## Key Concepts
- Trie with terminal weights for efficient prefix matching
- Dynamic insert/delete operations on Trie structure
- Weighted word-break DP with O(n × L) complexity where L = maxWordLen
- Both iterative bottom-up DP and memoized top-down DFS variants

## Code Example
```javascript
class TrieNode {
  constructor() {
    this.children = new Map();
    this.endWeight = 0;
    this.isEnd = false;
  }
}

class WeightedTrie {
  constructor() {
    this.root = new TrieNode();
    this.maxWordLen = 0;
  }

  insert(word, weight) {
    let node = this.root;
    for (const char of word) {
      if (!node.children.has(char)) {
        node.children.set(char, new TrieNode());
      }
      node = node.children.get(char);
    }
    node.isEnd = true;
    node.endWeight = weight;
    this.maxWordLen = Math.max(this.maxWordLen, word.length);
  }

  delete(word) {
    let node = this.root;
    for (const char of word) {
      if (!node.children.has(char)) return;
      node = node.children.get(char);
    }
    node.isEnd = false;
    node.endWeight = 0;
  }

  maxPartition(s) {
    const n = s.length;
    const dp = new Array(n + 1).fill(-1);
    dp[n] = 0;

    for (let i = n - 1; i >= 0; i--) {
      let node = this.root;
      for (let j = i; j < Math.min(n, i + this.maxWordLen); j++) {
        const char = s[j];
        if (!node.children.has(char)) break;
        node = node.children.get(char);
        if (node.isEnd && dp[j + 1] !== -1) {
          dp[i] = Math.max(dp[i], node.endWeight + dp[j + 1]);
        }
      }
    }
    return dp[0];
  }

  maxPartitionDFS(s, memo = {}) {
    if (s.length === 0) return 0;
    if (s in memo) return memo[s];

    let maxWeight = -1;
    let node = this.root;

    for (let i = 0; i < Math.min(s.length, this.maxWordLen); i++) {
      const char = s[i];
      if (!node.children.has(char)) break;
      node = node.children.get(char);

      if (node.isEnd) {
        const remaining = this.maxPartitionDFS(s.slice(i + 1), memo);
        if (remaining !== -1) {
          maxWeight = Math.max(maxWeight, node.endWeight + remaining);
        }
      }
    }
    memo[s] = maxWeight;
    return maxWeight;
  }
}
```

## Why This Is Asked
Tests the ability to blend BFS intuition with shortest-path techniques under a hop constraint and to reconstruct a path from augmented state.

## Key Concepts
- Augmented state graph: (node, hops)
- Dijkstra with 2D dist and predecessor tracking
- Path reconstruction from (node, hops) chain
- Time/space: O((N*H + M*H) log(N*H))

## Code Example

```javascript
function shortestPathWithHops(graph, S, T, H) {
  // graph: {u: [{to,w}, ...], ...}
  const dist = new Map();
  const prev = new Map();
  // min-heap assumed available: push({time, node, hops})
  const heap = new MinHeap((a,b)=>a.time-b.time);
  dist.set(`${S}|0`, 0);
  heap.push({time:0, node:S, hops:0});
  while (!heap.isEmpty()) {
    const {time,u,k} = heap.pop();
    if (time !== dist.get(`${u}|${k}`)) continue;
    for (const {to:v, w} of (graph[u] || [])) {
      const nk = k + 1;
      if (nk > H) continue;
      const nd = time + w;
      const key = `${v}|${nk}`;
      if (nd < (dist.get(key) ?? Infinity)) {
        dist.set(key, nd);
        prev.set(key, `${u}|${k}`);
        heap.push({time: nd, node: v, hops: nk});
      }
    }
  }
  let bestTime = Infinity; let bestKey = null;
  for (let k = 0; k <= H; k++) {
    const key = `${T}|${k}`;
    const d = dist.get(key);
    if (d != null && d < bestTime) { bestTime = d; bestKey = key; }
  }
  const path = [];
  if (bestKey) {
    let cur = bestKey;
    while (cur) {
      const [node] = cur.split('|');
      path.push(node);
      cur = prev.get(cur);
    }
    path.reverse();
  }
  return { time: bestTime, path };
}
```

